package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Mensaje corto entre la central y un domiciliario (tabla MENSAJE, RF-M4-06). Hay una conversación por
 * domiciliario.
 * <p>
 * EN: Short message between the dispatch office and a courier (MENSAJE table, RF-M4-06). There is one conversation per
 * courier.
 */
@Entity
@Table(name = "MENSAJE")
public class ChatMessage {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del domiciliario de la conversación. EN: The courier id of the conversation. */
    @Column(name = "DOMICILIARIO_ID", nullable = false) private Long courierId;
    /** Si lo escribió la central. EN: Whether the dispatch office wrote it. */
    @Column(name = "DE_CENTRAL", nullable = false) private boolean fromCentral;
    /** El nombre de quien escribió. EN: The name of the writer. */
    @Column(name = "AUTOR", nullable = false, length = 80) private String author;
    /** El texto del mensaje. EN: The message text. */
    @Column(name = "TEXTO", nullable = false, length = 300) private String text;
    /** La fecha en minutos de reloj. EN: The date in clock minutes. */
    @Convert(converter = MinutesConverter.class) @Column(name = "FECHA", nullable = false) private Double date;
    /** Si ya se leyó. EN: Whether it was already read. */
    @Column(name = "LEIDO", nullable = false) private boolean read;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected ChatMessage() {}

    /**
     * Crea un mensaje sin leer.
     * <p>
     * EN: Creates an unread message.
     *
     * @param courierId id del domiciliario de la conversación / courier id of the conversation
     * @param fromCentral true si lo escribió la central / true if the dispatch office wrote it
     * @param author nombre de quien escribe / name of the writer
     * @param text texto del mensaje / message text
     * @param date fecha en minutos de reloj / date in clock minutes
     */
    public ChatMessage(long courierId, boolean fromCentral, String author, String text, double date) {
        this.courierId = courierId; this.fromCentral = fromCentral; this.author = author; this.text = text; this.date = date;
    }

    /**
     * Marca el mensaje como leído.
     * <p>
     * EN: Marks the message as read.
     */
    public void markRead() { read = true; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del domiciliario de la conversación.
     * <p>
     * EN: Returns the courier id of the conversation.
     *
     * @return el id del domiciliario de la conversación / the courier id of the conversation
     */
    public Long getCourierId() { return courierId; }

    /**
     * Indica si lo escribió la central.
     * <p>
     * EN: Tells whether the dispatch office wrote it.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isFromCentral() { return fromCentral; }

    /**
     * Devuelve el nombre de quien escribió.
     * <p>
     * EN: Returns the name of the writer.
     *
     * @return el nombre de quien escribió / the name of the writer
     */
    public String getAuthor() { return author; }

    /**
     * Devuelve el texto del mensaje.
     * <p>
     * EN: Returns the message text.
     *
     * @return el texto del mensaje / the message text
     */
    public String getText() { return text; }

    /**
     * Devuelve la fecha en minutos de reloj.
     * <p>
     * EN: Returns the date in clock minutes.
     *
     * @return la fecha en minutos de reloj / the date in clock minutes
     */
    public Double getDate() { return date; }

    /**
     * Indica si ya se leyó.
     * <p>
     * EN: Tells whether it was already read.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isRead() { return read; }
}
